<?php require_once '../includes/config.php'; require_role('admin');$pdo=db();$revenue=$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='cancelled'")->fetchColumn();$orders=$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$customers=$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$stock=$pdo->query('SELECT COUNT(*) FROM products WHERE stock<5 AND status=1')->fetchColumn();$top=$pdo->query('SELECT p.name,SUM(oi.quantity) qty FROM order_items oi JOIN products p ON p.id=oi.product_id GROUP BY oi.product_id ORDER BY qty DESC LIMIT 10')->fetchAll();$title='Reports';require '../includes/header.php';?><h1 class="section-title">Sales & Inventory Reports</h1><div class="row g-3 mb-4"><div class="col-6 col-lg-3"><div class="stat"><small>Revenue</small><div class="num text-purple"><?=money($revenue)?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><small>Orders</small><div class="num text-purple"><?=$orders?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><small>Customers</small><div class="num text-purple"><?=$customers?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><small>Low stock</small><div class="num text-purple"><?=$stock?></div></div></div></div><div class="panel p-4"><h5>Top products by quantity sold</h5><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Units</th></tr></thead><tbody><?php foreach($top as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['qty'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require '../includes/footer.php'; ?>